mapper.select:
SELECT d.dong_code AS dongCode, d.sido_name AS sidoName, d.gugun_name AS gugunName, d.dong_name AS dongName, COUNT(p.park_id) AS parkCount FROM dongcodes d LEFT JOIN parks p ON p.dong_code = d.dong_code WHERE d.dong_code IN
#{dongCode}
GROUP BY d.dong_code, d.sido_name, d.gugun_name, d.dong_name ORDER BY d.dong_code
